  Lemma cnt_hb : forall r m1 (x1 x14 x20 x22 x23 x24 x25 x26 x27 x30 : word),
    2 <= r < 32768 ->
    (forall y20 y30, y30 = Z_to_bv 64 (Z.log2 r + 1) -> y20 = Z_to_bv 64 (2 ^ Z.log2 r) ->
